raw_text:
{
  "verifications": [
    {
      "fact_id": "F001",
      "verdict": "AMBIGUOUS",
      "verification_notes": "全国Byelawsが2005年にTransport Act 2000第219条に基づいて制定されたこと、TfL資産が適用除外となり独自Byelawsを持つこと、Merseyrailが独自Byelawsを持ち酒類規定以外は全国版と同じであることは確認できます。ただし、Merseyrailの除外改正は2013年12月に制定された一方、改正命令の施行は2014年1月18日です。「除外は2013年」と施行年の意味で読むと不正確です。([gov.uk](https://www.gov.uk/government/publications/railway-byelaws?utm_source=openai))"
    },
    {
      "fact_id": "F002",
      "verdict": "VERIFIED",
      "verification_notes": "現行全国鉄道Byelaw 7(1)は、運営者の書面許可がない場合、他人を不快にさせる形で歌うこと、または音を発生・再生する器具・物品・機器を使うことを禁じています。スマートフォンのスピーカー再生も、条文の条件を満たせば対象となりえます。条文に数値音量基準はありません。([assets.publishing.service.gov.uk](https://assets.publishing.service.gov.uk/media/694aa5551a2e540ccd8a54f8/dft-railway-byelaws-amendment-2025.pdf))"
    },
    {
      "fact_id": "F003",
      "verdict": "VERIFIED",
      "verification_notes": "Byelaw 6(8)は、鉄道上で他人の快適さまたは利便性を故意に妨げることを禁じています。Byelaw 7(1)とは別の条文・要件であり、個別のスピーカー再生が該当するかは状況によります。([assets.publishing.service.gov.uk](https://assets.publishing.service.gov.uk/media/694aa5551a2e540ccd8a54f8/dft-railway-byelaws-amendment-2025.pdf))"
    },
    {
      "fact_id": "F004",
      "verdict": "VERIFIED",
      "verification_notes": "全国Byelaw 24(1)は、Byelaw 17を除く違反について犯罪となり、標準罰金尺度レベル3以下の罰金がありうると定めています。DfTは2026年10月19日の発表で鉄道上の上限を£1,000と説明しています。これは上限であり、スピーカー再生に対する自動・定額の即時罰金ではありません。([assets.publishing.service.gov.uk](https://assets.publishing.service.gov.uk/media/694aa5551a2e540ccd8a54f8/dft-railway-byelaws-amendment-2025.pdf))"
    },
    {
      "fact_id": "F005",
      "verdict": "VERIFIED",
      "verification_notes": "Byelaw 24(2)は、違反中と合理的に信じる権限者から求められた人は直ちに退出しなければならず、求めに応じて違反をやめず、または退出しない場合、権限者が合理的な力で退去させられると定めています。権限者は権限行使の前に違反の性質を一般的な形で告げる必要があります。DfT発表の「次の駅で降ろされうる」はキャンペーン説明であり、条文の文言そのものではありません。([assets.publishing.service.gov.uk](https://assets.publishing.service.gov.uk/media/694aa5551a2e540ccd8a54f8/dft-railway-byelaws-amendment-2025.pdf))"
    },
    {
      "fact_id": "F006",
      "verdict": "VERIFIED",
      "verification_notes": "TfL Railway Byelaw 7(1)にも、書面許可がない場合に、他人を不快にさせる形で音を発生・再生する器具等を使うことを禁じる規定があります。違反は犯罪となりレベル3以下の罰金がありえ、退出要求・合理的な力による退去の規定もあります。掲載条文はLondon Underground、London Overground、DLR等のTfL鉄道網を対象とし、バス・トラム一般にそのまま適用される規則ではありません。施行日は2011年10月5日です。([content.tfl.gov.uk](https://content.tfl.gov.uk/railway-byelaws.pdf))"
    },
    {
      "fact_id": "F007",
      "verdict": "VERIFIED",
      "verification_notes": "National RailはQuiet Coachで音楽・動画・ゲームを使う場合にヘッドホンを使い、他人の迷惑にならない音量にするよう案内しています。また、Quiet Coachは全事業者にあるわけではなく、会社によって規則が異なる場合があると明記しています。([nationalrail.co.uk](https://www.nationalrail.co.uk/on-the-train/quiet-coaches/?utm_source=openai))"
    },
    {
      "fact_id": "F008",
      "verdict": "REJECTED",
      "verification_notes": "「過度に大きい音量の音楽」を過去12か月に見聞きし、移動中の安全感が低下したと回答した割合が38%、設問母数が4,654人という数値は確認できます。ただし調査対象は英国全体ではなくグレートブリテンの18歳以上で、調査で定義する公共交通はバス・列車・地下鉄・ライトレール・トラム等です。Ledgerの「英国在住」やタクシー等を含む対象群の説明は正確ではありません。また、この数値はスピーカー再生のみを示しません。([assets.publishing.service.gov.uk](https://assets.publishing.service.gov.uk/media/697338e6d8adeaf266040588/personal-safety-on-transport.pdf))"
    },
    {
      "fact_id": "F009",
      "verdict": "VERIFIED",
      "verification_notes": "ロンドン市長の2026年6月18日回答は、TfL調査の1,000人のうち70%が、ヘッドホンなしの大音量音楽や通話を迷惑と感じると述べています。音に敏感な人、例として自閉症の人への影響にも触れています。調査方法や設問詳細は回答文には示されていないため、Ledgerの留保も妥当です。([london.gov.uk](https://www.london.gov.uk/who-we-are/what-london-assembly-does/questions-mayor/find-an-answer/loud-music-tubes))"
    },
    {
      "fact_id": "F010",
      "verdict": "VERIFIED",
      "verification_notes": "市長回答によれば、「Headphones On」は2025年夏にElizabeth lineのポスターで始まり、その後バス、DLR、London Overground、Tube、Tramへ拡大しました。Tubeの車内放送には現時点で含まれず、安全・保安・運行情報を優先すると説明されています。制服着用の交通支援執行職員は、必要に応じて携帯電話利用に関して対応し、適切と判断すれば執行措置を取るとの説明も確認できます。([london.gov.uk](https://www.london.gov.uk/who-we-are/what-london-assembly-does/questions-mayor/find-an-answer/loud-music-tubes))"
    },
    {
      "fact_id": "F011",
      "verdict": "VERIFIED",
      "verification_notes": "DfTは2026年10月19日に、鉄道業界主導の全国キャンペーン開始を発表しました。音声での案内を含む展開方針が示され、多くの事業者がウェブサイト、SNS、車内、駅でポスターやアナウンス等を行うとしています。「多くの事業者」の展開予定であり、全列車・全媒体で実施済みという意味ではありません。([gov.uk](https://www.gov.uk/government/news/share-the-journey-not-the-noise-government-launches-measures-to-prevent-noise-and-antisocial-behaviour-on-transport))"
    },
    {
      "fact_id": "F012",
      "verdict": "VERIFIED",
      "verification_notes": "Bus Services Act 2025に関係する地方交通当局のバスByelaws制定権限（イングランド、ロンドン外）とTfLの権限は、2026年8月5日に施行されました。個々のByelawは運輸大臣の承認を得るまで執行できない点も、DfTガイダンスに明記されています。権限の施行と、各地域の個別規則の制定・承認・施行は別です。([legislation.gov.uk](https://www.legislation.gov.uk/uksi/2026/834/regulation/2/made?utm_source=openai))"
    },
    {
      "fact_id": "F013",
      "verdict": "VERIFIED",
      "verification_notes": "2026年10月19日のDfTガイダンスは、地方当局が検討できる例示条文として、他人を不快にさせる形で音を発生・再生する器具等を使うことの禁止を示しています。また、イヤホン・ヘッドホンなしの音楽・動画再生を過度な騒音の例に挙げています。これはモデル例・ガイダンスであり、全地域で制定済みの規則ではありません。([gov.uk](https://www.gov.uk/government/publications/using-bus-byelaws-to-tackle-nuisance-behaviour/using-bus-byelaws-to-tackle-nuisance-behaviour?utm_source=openai))"
    },
    {
      "fact_id": "F014",
      "verdict": "VERIFIED",
      "verification_notes": "DfTのバスByelaws執行に関する法定ガイダンスは、まず対話し、規則や他の乗客への影響を説明し、それでも行動が変わらなければ執行する「Engage, Educate, Enforce」方式を強く推奨しています。FPNは最大£100で、裁判での訴追に代わる選択肢ですが、当局に発行義務はありません。執行担当は権限付与された職員や警察官で、バス運転手が執行を担うのではありません。個別Byelawの承認が前提です。([gov.uk](https://www.gov.uk/government/publications/using-bus-byelaws-to-tackle-nuisance-behaviour/using-bus-byelaws-to-tackle-nuisance-behaviour?utm_source=openai))"
    },
    {
      "fact_id": "F015",
      "verdict": "VERIFIED",
      "verification_notes": "2025年1月30日の議会回答は、BTPが鉄道網で反社会的行為を取り締まり、61016への報告がASBへの対応と資源配分のための情報提供に重要な役割を果たすと説明しています。回答は音楽再生に限定した件数や個別処理実績を示していないため、Ledgerの留保は適切です。([questions-statements.parliament.uk](https://questions-statements.parliament.uk/written-questions/detail/2025-01-27/26675?utm_source=openai))"
    }
  ]
}
